import React, { useState } from "react";
import axios from "axios";
import "./AuthPage.css";

const api = axios.create({ baseURL: "http://localhost:8000" });

export default function AuthPage({ onLogin }) {
  const [tab, setTab] = useState("login");
  const [form, setForm] = useState({ username: "", email: "", password: "" });
  const [msg, setMsg] = useState(null);
  const [loading, setLoading] = useState(false);

  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg(null);
    setLoading(true);
    try {
      if (tab === "signup") {
        await api.post("/auth/register", {
          username: form.username,
          email: form.email,
          password: form.password,
        });
        setMsg({ type: "success", text: "Account created! Please log in." });
        setTab("login");
        setForm({ username: "", email: "", password: "" });
      } else {
        const res = await api.post(
          "/auth/login",
          new URLSearchParams({ username: form.username, password: form.password }),
          { headers: { "Content-Type": "application/x-www-form-urlencoded" } }
        );
        onLogin(res.data.access_token, form.username);
      }
    } catch (err) {
      setMsg({ type: "error", text: err.response?.data?.detail || "Something went wrong." });
    }
    setLoading(false);
  };

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">
          <span>🛍️</span>
          <h1>ShopTrac</h1>
          <p>Your Online Electronics Store</p>
        </div>

        <div className="auth-tabs">
          <button className={`auth-tab ${tab === "login" ? "active" : ""}`} onClick={() => { setTab("login"); setMsg(null); }}>
            Login
          </button>
          <button className={`auth-tab ${tab === "signup" ? "active" : ""}`} onClick={() => { setTab("signup"); setMsg(null); }}>
            Sign Up
          </button>
        </div>

        {msg && <div className={`auth-${msg.type}`} style={{ marginBottom: 14 }}>{msg.text}</div>}

        <form className="auth-form" onSubmit={handleSubmit}>
          <input
            placeholder="Username"
            value={form.username}
            onChange={set("username")}
            required
            autoComplete="username"
          />
          {tab === "signup" && (
            <input
              type="email"
              placeholder="Email"
              value={form.email}
              onChange={set("email")}
              required
              autoComplete="email"
            />
          )}
          <input
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={set("password")}
            required
            autoComplete={tab === "login" ? "current-password" : "new-password"}
          />
          <button className="auth-submit" type="submit" disabled={loading}>
            {loading ? "Please wait..." : tab === "login" ? "Login" : "Create Account"}
          </button>
        </form>
      </div>
    </div>
  );
}
